registerCombo({
  comboId: 1075,
  members: ["Goibne_Armor_IL", "Goibne_Helmet_IL", "Goibne_Shoulder_IL", "Goibne_Boots_IL"],
  onActive(ctx) {
    let $hp, $r, $sum;
    ctx.bonus("bVit", 5);
    ctx.bonus("bMaxSPrate", 5);
    ctx.bonus("bDef", 5);
    ctx.bonus("bMdef", 15);
    ctx.bonus2("bSubEle", "Ele_Water", 10);
    ctx.bonus2("bSubEle", "Ele_Earth", 10);
    ctx.bonus2("bSubEle", "Ele_Fire", 10);
    ctx.bonus2("bSubEle", "Ele_Wind", 10);
    $hp = 15;
    ctx.__indexAssign(ctx.__index($r, 0), ctx.getequiprefinerycnt("EQI_ARMOR"));
    ctx.__indexAssign(ctx.__index($r, 1), ctx.getequiprefinerycnt("EQI_HEAD_TOP"));
    ctx.__indexAssign(ctx.__index($r, 2), ctx.getequiprefinerycnt("EQI_GARMENT"));
    ctx.__indexAssign(ctx.__index($r, 3), ctx.getequiprefinerycnt("EQI_SHOES"));
    $sum = ctx.__index($r, 0) + ctx.__index($r, 1) + ctx.__index($r, 2) + ctx.__index($r, 3);
    if (ctx.__index($r, 0) >= 7 && ctx.__index($r, 1) >= 7 && ctx.__index($r, 2) >= 7 && ctx.__index($r, 3) >= 7) {
      $hp = $hp + 10;
    }
    ctx.bonus("bMaxHPrate", $hp);
    if ($sum >= 36) {
      ctx.bonus("bFixedCast", -700);
      if ($sum >= 40) {
        ctx.bonus("bDelayrate", -20);
      }
    }

  },
});

