registerCombo({
  comboId: 1142,
  members: ["SeraphimCoronet", "Feather_Of_Seraphim"],
  onActive(ctx) {
    let $i, $cast, $sub, $heal;
    $i = ctx.readparam("bInt");
    $cast = -(ctx.readparam("bInt") / 8);
    $sub = 2;
    $heal = 5;
    if ($i >= 120) {
      $cast = $cast - 10;
      $sub = $sub + 6;
      $heal = $heal + 25;
    } else
    if ($i >= 108) {
      $cast = $cast - 4;
      $sub = $sub + 2;
      $heal = $heal + 10;
    }
    ctx.bonus("bVariableCastrate", $cast);
    ctx.bonus2("bSubRace", "RC_DemiHuman", $sub);
    ctx.bonus2("bSubRace", "RC_Player_Human", $sub);
    ctx.bonus("bHealPower", $heal);
    ctx.bonus("bAddItemHealRate", $heal);
    ctx.bonus2("bVariableCastrate", "AB_CHEAL", -100);
    ctx.bonus2("bResEff", "Eff_Bleeding", 10000);
    ctx.bonus2("bResEff", "Eff_Confusion", 10000);

  },
});

