registerCombo({
  comboId: 1414,
  members: ["Shoes_Of_Punishment", "Holy_Stick"],
  onActive(ctx) {
    let $r, $cast, $magic, $dmg;
    $r = ctx.getequiprefinerycnt("EQI_HAND_R");
    $cast = -5 * ctx.getskilllv("AB_ORATIO");
    ctx.bonus2("bVariableCastrate", "AB_JUDEX", $cast);
    ctx.bonus2("bVariableCastrate", "AB_ADORAMUS", $cast);
    if ($r >= 7) {
      $magic = 30;
      if ($r >= 9) {
        $magic = $magic + 20;
        $dmg = 20;
      }
      ctx.bonus2("bMagicAddRace", "RC_Demon", $magic);
      ctx.bonus2("bMagicAddRace", "RC_Undead", $magic);
      ctx.bonus2("bMagicAddEle", "Ele_Undead", $magic);
      ctx.bonus2("bMagicAddEle", "Ele_Dark", $magic);
    }
    ctx.bonus2("bSkillAtk", "AB_ADORAMUS", $dmg + 10 * (ctx.getskilllv("AB_LAUDAAGNUS") + ctx.getskilllv("AB_LAUDARAMUS") + ctx.getskilllv("AB_CLEARANCE")));

  },
});

